.accordion {
  display: flex;
  flex-direction: column;
}

/* A rule BETWEEN two sections, never around the set. The outer lines drew a box
 * that nothing asked for: inside a card, one item wore a hairline above and
 * below and read as a divider that had lost its section (owner, 23.08). The
 * same surface rule as everywhere else here — what separates blocks is space,
 * and a line is only for the seam between two of them. */
.accordion-item + .accordion-item {
  border-block-start: var(--surface-edge);
}

.accordion-heading {
  margin: 0;
  font: inherit;
}

.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  inline-size: 100%;
  padding: var(--space-3) var(--space-1);
  background: transparent;
  color: var(--foreground);
  font-size: var(--font-base);
  font-weight: var(--font-weight-medium);
  text-align: start;
  transition: color var(--duration-fast);
}
.accordion-header:hover {
  color: var(--primary-accent);
}
.accordion-header:focus-visible {
  outline: var(--focus-ring);
  outline-offset: var(--focus-ring-inset);
  border-radius: var(--radius-sm);
}
.accordion-header:disabled {
  opacity: var(--disabled-opacity);
  cursor: not-allowed;
}

/* A column of blocks whose headers ARE the section heads of the column they sit in: the same
   voice as <SectionLabel>, so a block does not shrink its own title just because it gained a
   chevron. */
.accordion[data-size='lg'] .accordion-header {
  font-family: var(--font-family-display);
  font-size: var(--font-lg);
  line-height: var(--leading-tight);
}

.accordion-chevron {
  flex-shrink: 0;
  color: var(--icon-muted);
  transition: transform var(--duration-fast);
}
.accordion-item[data-open] .accordion-chevron {
  transform: rotate(180deg);
}

.accordion-panel {
  padding: 0 var(--space-1) var(--space-4);
  color: var(--muted-foreground);
  font-size: var(--font-base);
  line-height: var(--leading-normal);
}

import './Accordion.css'
import { useId, useState, type KeyboardEvent, type ReactNode } from 'react'
import { cn } from '../lib/cn'
import { Icon } from '../Icon'

export type AccordionItem = {
  /** Stable id used for open state and ARIA wiring. */
  id: string
  title: ReactNode
  content: ReactNode
  /** Shown but not openable. */
  disabled?: boolean
}

type Props = {
  items: AccordionItem[]
  /** true = several panels open at once; false (default) = one at a time. */
  multiple?: boolean
  /** Ids open on first render, when the accordion keeps its own state. */
  defaultOpen?: string[]
  /**
   * Which ids are open, when the SCREEN keeps that state — a step list whose
   * progress the page owns, a findings panel a URL can deep-link into. Same pair
   * as `<Tree>`'s `expandedIds` / `onExpandedChange`, and the same rule: pass
   * both or neither.
   *
   * Written because two screens in one product hand-rolled a disclosure rather
   * than take this component, and the reason both times was that the open state
   * lives outside it. (2026-09-04)
   */
  openIds?: string[]
  /** Fires with the ids that are open after the press. */
  onOpenChange?: (ids: string[]) => void
  /** Header voice: `md` (default, body size) or `lg` — the section-head size, for a column of
   *  blocks whose titles are the headings of the page beside them. */
  size?: 'md' | 'lg'
  /** Heading level of each header (default 3). Set it to the level the outline is at where the
   *  accordion sits: a stack of blocks straight under the page title is at 2, not 3, and a skipped
   *  level is a section a screen reader cannot walk to. */
  headingLevel?: 2 | 3 | 4
  className?: string
}

/* Disclosure list: a stack of headers that each reveal a panel. The header is a
 * real <button> (Space/Enter toggle it, focus ring, disabled honoured); Arrow
 * Up/Down/Home/End move between headers, matching the WAI-ARIA accordion. State
 * is owned here — pass `multiple` to allow several panels open at once. */
/* Monolithic because an accordion is one list with one state: the items, whether
 * more than one may stand open, who keeps that state, and the two things a
 * header has to agree with the page about — its size and its heading level.
 * There is no half of this a caller could use alone. */
export function Accordion({ items, multiple = false, defaultOpen = [], openIds, onOpenChange, size = 'md', headingLevel = 3, className }: Props) {
  const [inner, setInner] = useState<string[]>(defaultOpen)
  /* Controlled when the caller passes ids, uncontrolled otherwise — and the
     toggle below computes the next list either way, so the caller receives the
     same answer the component would have kept. */
  const open = openIds ?? inner
  const setOpen = (next: (cur: string[]) => string[]) => {
    const value = next(open)
    if (!openIds) setInner(value)
    onOpenChange?.(value)
  }
  const baseId = useId()
  const Heading = `h${headingLevel}` as const

  const toggle = (id: string) => {
    setOpen((cur) => {
      const isOpen = cur.includes(id)
      if (multiple) return isOpen ? cur.filter((x) => x !== id) : [...cur, id]
      return isOpen ? [] : [id]
    })
  }

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(e.key)) return
    const headers = Array.from(e.currentTarget.querySelectorAll<HTMLButtonElement>('.accordion-header:not(:disabled)'))
    const i = headers.findIndex((h) => h === document.activeElement)
    if (i === -1) return
    e.preventDefault()
    let next = i
    if (e.key === 'ArrowDown') next = (i + 1) % headers.length
    else if (e.key === 'ArrowUp') next = (i - 1 + headers.length) % headers.length
    else if (e.key === 'Home') next = 0
    else if (e.key === 'End') next = headers.length - 1
    headers[next]?.focus()
  }

  return (
    // eslint-disable-next-line jsx-a11y/no-static-element-interactions -- the container only delegates arrow-key focus to its header buttons; it is not itself interactive
    <div className={cn('accordion', className)} data-size={size} onKeyDown={onKeyDown}>
      {items.map((item) => {
        const isOpen = open.includes(item.id)
        const headerId = `${baseId}-h-${item.id}`
        const panelId = `${baseId}-p-${item.id}`
        return (
          <div className="accordion-item" key={item.id} data-open={isOpen || undefined}>
            <Heading className="accordion-heading">
              <button
                type="button"
                id={headerId}
                className="accordion-header"
                aria-expanded={isOpen}
                aria-controls={panelId}
                disabled={item.disabled}
                onClick={() => toggle(item.id)}
              >
                <span className="accordion-title">{item.title}</span>
                <Icon name="arrow_drop_down" className="accordion-chevron" />
              </button>
            </Heading>
            {isOpen && (
              <div className="accordion-panel" id={panelId} role="region" aria-labelledby={headerId}>
                {item.content}
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}
